cd /app; python - <<'E'
import glob,re,collections
c=collections.defaultdict(collections.Counter)
for f in sorted(glob.glob('logs/ci/*.log')):
    t=open(f).read()
    for b in re.split(r'\n(?=---- )',t)[1:]:
        name=b.split('\n')[0][5:].strip()
        if 'test_stock_report' in name or 'test_aging_report' in name or 'test_putaway' in name or 'roundtrip' in name or 'format_weight' in name:
            key=re.findall(r"^[-+?] .*$",b,re.M)[:3]
            c[name][ ' / '.join(key)[:150]]+=1
for n,v in c.items():
    print(n)
    for k,x in v.items(): print('  ',x,k)
E
grep -n "def test_aging_report" -A12 tests/test_reports.py
